import requests, xml.etree.ElementTree as ET
pmid='25428920'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':pmid,'retmode':'xml'},timeout=30)
root=ET.fromstring(r.text)
for tag in ['ArticleTitle','AbstractText','Journal','PubDate','ELocationID','PMID']:
    vals=[]
    for e in root.iter(tag):
        txt=''.join(e.itertext()).strip()
        if txt: vals.append(txt)
    if vals: print(tag,':',' | '.join(vals))
print('DOI', [e.text for e in root.iter('ArticleId') if e.attrib.get('IdType')=='doi'])
